import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from cleanup import archive_name, strip_log_suffix


def test_strips_simple_log_suffix():
    assert strip_log_suffix("app.log") == "app"


def test_glob_is_not_mangled():
    # 'glob.log'.strip('.log') would wrongly return 'b'
    assert strip_log_suffix("glob.log") == "glob"


def test_login_is_not_mangled():
    # trailing chars of 'login' are all in the strip set
    assert strip_log_suffix("login.log") == "login"


def test_ollog_is_not_mangled():
    assert strip_log_suffix("ollog.log") == "ollog"


def test_name_without_suffix_unchanged():
    assert strip_log_suffix("readme") == "readme"


def test_only_removes_one_suffix():
    assert strip_log_suffix("a.log.log") == "a.log"


def test_archive_name():
    assert archive_name("glob.log", "2026-01-05") == "glob-2026-01-05.gz"

